do $q$
declare v_quiz uuid; v_q uuid; v_sira int; r jsonb; o jsonb; j int;
begin
  select z.id into v_quiz from public.quizzes z join public.modules m on m.id = z.module_id
   where m.ad = 'Uçuş Kontrol & Kurulum' and z.zorluk = 'orta' limit 1;
  if v_quiz is null then raise notice 'Quiz yok, atlanıyor: Uçuş Kontrol & Kurulum orta'; return; end if;
  select coalesce(max(sira), 0) into v_sira from public.questions where quiz_id = v_quiz;
  for r in select * from jsonb_array_elements($json$[{"m":"SBUS desteği olmayan bir kumanda alıcısından Pixhawk kartına sinyal aktarmak için hangi donanım ve yöntem kullanılır?","a":"SBUS desteği olmayan alıcılarda kanalları tek kabloda toplamak için PPM Encoder kullanılır.","o":[["PPM Encoder modülü kullanılır; tüm kanallar tek bir kablo üzerinden kodlanarak aktarılır",true],["Her kanal için ayrı kablolar doğrudan Pixhawk'ın RC girişine takılır",false],["Telemetri modülü doğrudan alıcıya bağlanarak PPM sinyaline dönüştürülür",false],["Pixhawk bu durumda harici modüle ihtiyaç duymaz, PWM girişlerini doğrudan destekler",false]]},{"m":"Mission Planner ile kablolu (USB) bağlantı kurarken seri port baud rate değeri kaç seçilmelidir?","a":"Kablolu bağlantı için 115.200, telemetri modülü için 57.600 baud seçilir.","o":[["57.600",false],["115.200",true],["9.600",false],["921.600",false]]},{"m":"Videoya göre hekzakopter gibi keskin köşeli olmayan yapılarda ivmeölçer (accelerometer) kalibrasyonu nasıl yapılmalıdır?","a":"Kalibrasyon için kart düz zeminde, gövdeye monte edilmeden yapılır.","o":[["Uçuş kartı gövdeye monte edilmeden önce, düz bir zeminde kalibre edilir",true],["Kalibrasyon her zaman araç tamamen monte edildikten sonra yapılmalıdır",false],["Su terazisine gerek yoktur, kart kendi kendini dengeler",false],["Yalnızca kartın ön yüzü yere bakacak şekilde tek pozisyonda kalibrasyon yeterlidir",false]]},{"m":"Güç kartının (Power Module) Pixhawk'a bağlantı kablosu kart üzerinde hangi porta takılır?","a":"Güç modülü Pixhawk'ın Power portuna bağlanır ve voltaj/akım bilgisi buradan okunur.","o":[["Power portuna",true],["RC In portuna",false],["Aux Out portuna",false],["USB girişine",false]]},{"m":"Telemetri modülü Pixhawk üzerinde hangi porta bağlanır?","a":"Kablosuz telemetri modülleri TELEM1 veya TELEM2 portlarına takılır.","o":[["TELEM 1 veya TELEM 2 portuna",true],["I2C portuna",false],["Main Out portuna",false],["Buzzer portuna",false]]},{"m":"Pusula (compass) kalibrasyonu Mission Planner'da hangi menüden başlatılır?","a":"Pusula kalibrasyonu Initial Setup > Compass bölümünden yapılır.","o":[["Initial Setup altındaki Compass seçeneğinden",true],["Radio Calibration sekmesinden",false],["Flight Modes sekmesinden",false],["HW Monitor ekranındaki calibrate butonundan",false]]},{"m":"Pusula kalibrasyonu sırasında hekzakopter nasıl hareket ettirilmelidir?","a":"Manyetik alan verisi küre çizer gibi her yönden toplanmalıdır.","o":[["Tüm eksenlerde (sağa, sola, öne, arkaya, baş aşağı) döndürülerek her açıdan veri toplanır",true],["Yalnızca kendi ekseni etrafında saat yönünde 360 derece döndürülür",false],["Sabit bir masada 30 saniye hareketsiz bekletilir",false],["Burnu gökyüzüne bakacak şekilde dikey tutulur",false]]},{"m":"Radio calibration (kumanda kalibrasyonu) sırasında stick'ler nasıl hareket ettirilmelidir?","a":"Uç noktalara gidilerek minimum ve maksimum PWM değerleri kaydedilir.","o":[["Tüm hareket sınırlarına (en üst, en alt, sağ ve sol uç noktalara) kadar",true],["Orta pozisyonda bırakılıp calibrate'e basılır",false],["Throttle tamamen yukarıda sabit tutulur, diğer kollara dokunulmaz",false],["Kumanda kapatılır",false]]},{"m":"HML650 toplanabilir iniş takımının sinyal kablosu Pixhawk'ta genellikle nereye bağlanır?","a":"İniş takımı kontrol sinyali boş bir Aux Out kanalından alınır.","o":[["Aux Out veya boş bir çıkış kanalına",true],["Doğrudan I2C portuna",false],["Power modülü girişine",false],["USB portuna",false]]},{"m":"Toplanabilir iniş takımının güç beslemesi genellikle nereden sağlanır?","a":"Servolar yüksek akım çektiği için PDB veya pil üzerinden beslenir.","o":[["Güç dağıtım kartından (PDB) veya doğrudan uçuş pilinden",true],["Pixhawk'ın 5V çıkış pinlerinden",false],["GPS modülü üzerinden",false],["Telemetri modülünün beslemesinden",false]]},{"m":"Mission Planner'da iniş takımı fonksiyonunu aktif etmek için ne yapılır?","a":"İlgili kanalın fonksiyonu parametre listesinden Landing Gear'a atanır.","o":[["Full Parameter List'ten ilgili RC kanalının fonksiyonu Landing Gear olarak ayarlanır",true],["Compass calibration sekmesi kullanılır",false],["Radio calibration menüsünden otomatik tanımlanır",false],["Motor Test bölümünden açılır",false]]},{"m":"MAVLink RGB LED kontrol kartı Pixhawk'ta hangi porta bağlanır?","a":"LED kartı verileri TELEM 2 portundan alır.","o":[["Telemetry 2 (TELEM 2) portu",true],["GPS portu",false],["I2C splitter portu",false],["Main Out 1-6 pinleri",false]]},{"m":"RGB LED kartının ayarlarını bilgisayardan yapmak için hangi araç kullanılır?","a":"LED kartına parametre yüklemek için FTDI arayüz kartı kullanılır.","o":[["FTDI dönüştürücü kartı",true],["PPM Encoder modülü",false],["I2C çoklayıcı board",false],["Servo sinyal test cihazı",false]]},{"m":"LED yazılımında düşük pil uyarısı (battery alarm voltage) videoda kaç volt olarak belirlenmiştir?","a":"Düşük pil eşiği 10.5 V olarak girilmiştir.","o":[["10.5 Volt",true],["11.1 Volt",false],["12.6 Volt",false],["9.6 Volt",false]]},{"m":"Autotune agresiflik (aggressiveness) parametresinin varsayılan değeri kaçtır?","a":"Videoda autotune aggressiveness varsayılan değeri 0.1 olarak belirtilmiştir.","o":[["0.1",true],["0.05",false],["1.0",false],["50",false]]},{"m":"Autotune'da hangi eksenlerin ayarlanacağı hangi parametreyle seçilir?","a":"Roll, pitch ve yaw eksenleri AUTOTUNE_AXES ile seçilir.","o":[["AUTOTUNE_AXES",true],["ATC_RAT_RLL_P",false],["MOT_BAT_VOLT_MAX",false],["RC_FEEL",false]]},{"m":"Volt ve amper kalibrasyonu Mission Planner'da hangi sekme altından yapılır?","a":"Gerilim ve akım sensörü kalibrasyonu Battery Monitor menüsündedir.","o":[["Initial Setup > Battery Monitor",true],["Initial Setup > Compass",false],["Flight Modes",false],["Hardware Options",false]]},{"m":"Mission Planner'da okunan voltaj ile multimetreyle ölçülen gerçek voltaj arasındaki fark nasıl giderilir?","a":"Gerçek voltaj girilince kalibrasyon oranı otomatik hesaplanır.","o":[["Multimetreyle ölçülen gerçek değer ilgili kutucuğa yazılarak oran yeniden hesaplatılır",true],["Yalnızca pilin hücre sayısı değiştirilir",false],["Güç modülünün kabloları ters çevrilir",false],["Pixhawk'a reset atılır",false]]},{"m":"Amper kalibrasyonunun doğru yapılabilmesi için pilden çekilen akım neyle doğrulanır?","a":"Akım kalibrasyonu için gerçek akım pens ampermetreyle ölçülür.","o":[["Pens ampermetre (clamp meter) ile gerçek akım ölçülerek",true],["Motor etiket değerleri toplanarak",false],["ESC kalibrasyon sesleri dinlenerek",false],["GPS uydu sayısına bakılarak",false]]},{"m":"Mission Planner'da beta yazılım sürümlerini görebilmek için ne yapılmalıdır?","a":"Beta sürümler Install Firmware ekranındaki Beta Firmwares bağlantısıyla listelenir.","o":[["Install Firmware ekranındaki 'Beta Firmwares' seçeneğine tıklanır",true],["İnternet bağlantısı tamamen kesilir",false],["Full Parameter List'ten beta_mode parametresi 1 yapılır",false],["Pixhawk reset tuşuna basılı tutulurken güncelleme başlatılır",false]]},{"m":"ChibiOS'un eski NuttX'e göre Pixhawk kartına sağladığı temel avantaj nedir?","a":"ChibiOS ArduPilot için daha yüksek kararlılık ve performans sağlar.","o":[["Daha iyi gerçek zamanlı performans, kararlı bellek yönetimi ve daha düşük gecikme",true],["Kartın fiziksel ağırlığını azaltması",false],["Pil şarj süresini yarıya indirmesi",false],["GPS bağlanma süresini tamamen ortadan kaldırması",false]]}]$json$::jsonb) loop
    if exists (select 1 from public.questions where quiz_id = v_quiz and metin = r->>'m') then continue; end if;
    v_sira := v_sira + 1;
    insert into public.questions (quiz_id, metin, sira, aciklama)
      values (v_quiz, r->>'m', v_sira, r->>'a') returning id into v_q;
    j := 0;
    for o in select * from jsonb_array_elements(r->'o') loop
      j := j + 1;
      insert into public.question_options (question_id, metin, dogru, sira)
        values (v_q, o->>0, (o->>1)::boolean, j);
    end loop;
  end loop;
end $q$;

