  if v_quiz is null then raise notice 'Quiz yok, atlanıyor: Uçuş Kontrol & Kurulum zor'; return; end if;
  select coalesce(max(sira), 0) into v_sira from public.questions where quiz_id = v_quiz;
  for r in select * from jsonb_array_elements($json$[{"m":"Pixhawk'a güncel yazılım yüklerken (Install Firmware) doğru işlem sırası hangisidir?","a":"Model seçilip onay verildikten sonra kart çıkarılır ve 30 saniye içinde tekrar takılır.","o":[["Initial Setup'tan Install Firmware seçilir, uygun model (hexa) tıklanır, 'Evet' denir, kart çıkarılıp 30 saniye içinde tekrar takılır",true],["Doğrudan Connect'e basılır, açılan menüden Update seçilir ve kart hiç sökülmeden güncellenir",false],["Önce Full Parameter List'ten tüm parametreler silinir, sonra model seçilir ve kart takılı bırakılır",false],["Kart bilgisayardan çıkarılmışken Mission Planner'da Upload'a basılır, sonra kart takılır",false]]},{"m":"Tek I2C portuna birden fazla cihaz (örneğin harici pusula ve başka modüller) bağlanmak istendiğinde ne kullanılır?","a":"Tek I2C portunu çoğaltmak için I2C splitter board kullanılır.","o":[["I2C splitter (çoklayıcı board)",true],["PPM Encoder modülü",false],["Cihazların kabloları doğrudan paralel bağlanır",false],["USB hub",false]]},{"m":"Mission Planner'da güç modülünün volt ve amper kalibrasyonu yapılırken hangi değerler ayarlanır?","a":"Gerilim ve akım çarpanları, multimetre/pens ampermetre ölçümüne göre ayarlanır.","o":[["Voltaj bölücü oranı ve volt başına amper (Amps per Volt) değeri",true],["Yalnızca motor KV değerleri",false],["Pervane çapı ve ağırlık",false],["Baud rate ve RSSI oranları",false]]},{"m":"Alıcı sinyali kesildiğinde (RC failsafe) kopterin hangi modlara geçmesi sağlanabilir? (birden çok)","a":"Sinyal kaybında güvenlik için genellikle RTL veya Land atanır.","o":[["RTL (Return to Launch)",true],["Land (iniş)",true],["Acro (akrobasi) modu",false],["Stabilize modunda sabit kalmak",false]]},{"m":"İlk uçuş öncesi pre-arm kontrollerinde hangi durum motorların arm edilmesini engeller?","a":"GPS fix yokluğu veya pusula hataları arm'ı engeller.","o":[["GPS 3D fix alınmamış olması veya pusula hata oranının yüksek olması",true],["Pervanelerin renklerinin farklı olması",false],["Telemetri baud rate'inin 57600 olması",false],["Pil voltajının tam dolu olması",false]]},{"m":"İniş takımı servo limitleri ayarlanırken nelere dikkat edilmelidir?","a":"Yanlış PWM limitleri servoyu zorlayıp yakabilir veya mekanizmayı sıkıştırabilir.","o":[["Mekanik sıkışmayı önlemek için PWM min ve max değerleri hassas ayarlanmalıdır",true],["PWM değerleri maksimumda sabit bırakılmalıdır",false],["Yalnızca reverse işaretlenip limitlere bakılmaz",false],["Kalibrasyon için motorların sökülmesi gerekir",false]]},{"m":"Kumanda sinyali kesildiğinde (RC failsafe) arka LED'ler hangi renkte yanacak şekilde ayarlanmıştır?","a":"RC bağlantısı koptuğunda arka LED'ler mavi yanar.","o":[["Mavi",true],["Yeşil",false],["Kırmızı",false],["Beyaz",false]]},{"m":"TELEM 2 portunun veri akışını ayarlamak için Mission Planner'da hangi adımlar izlenir? (birden çok)","a":"TELEM 2 çıkış oranları SR2 parametre grubundadır.","o":[["Full Parameter List menüsüne girilir",true],["Arama alanına 'SR2' yazılır ve ilgili parametreler düzenlenir",true],["Arama alanına 'GPS' yazılır",false],["Standard Params sekmesinden 'TELEM_RATE' seçilir",false]]},{"m":"FTDI kartı ile LED kontrol kartı bilgisayara bağlanırken seri iletişim pinleri nasıl bağlanmalıdır?","a":"Seri haberleşmede TX ve RX uçları çapraz bağlanır.","o":[["FTDI TX ucu LED kartının RX ucuna, RX ucu TX ucuna (çapraz)",true],["TX ucu TX ucuna, RX ucu RX ucuna",false],["Yalnızca GND bağlanıp sinyal pinleri boş bırakılır",false],["Yalnızca VCC ve GND yeterlidir",false]]},{"m":"Autotune sonrası kumanda tepki hissini PID değerlerine dokunmadan yumuşatmak için hangi parametre kullanılır?","a":"Kumanda hissi RC_FEEL parametresiyle ayarlanır.","o":[["RC_FEEL",true],["FILT",false],["MOT_BAT_CURR_MAX",false],["BATT_AMP_PERVLT",false]]},{"m":"Videoya göre 13 inç ve üzeri büyük pervaneli hekzakopterlerde Autotune öncesi filtreleme için FILT değeri kaça ayarlanmalıdır?","a":"Büyük pervanelerde titreşimleri sönümlemek için roll ve pitch FILT değeri 10 yapılır.","o":[["10",true],["50",false],["0 (filtre kapatılır)",false],["Yalnızca motor PWM filtreleri değiştirilir",false]]}]$json$::jsonb) loop
    if exists (select 1 from public.questions where quiz_id = v_quiz and metin = r->>'m') then continue; end if;
