do $q$
declare v_quiz uuid; v_q uuid; v_sira int; r jsonb; o jsonb; j int;
begin
  select z.id into v_quiz from public.quizzes z join public.modules m on m.id = z.module_id
   where m.ad = 'Aerodinamik ve Uçuş Mekaniği' and z.zorluk = 'orta' limit 1;
  if v_quiz is null then raise notice 'Quiz yok, atlanıyor: Aerodinamik ve Uçuş Mekaniği orta'; return; end if;
  select coalesce(max(sira), 0) into v_sira from public.questions where quiz_id = v_quiz;
  for r in select * from jsonb_array_elements($json$[{"m":"Sabit hızla ve dengede uçan bir hava aracında hangi kuvvet çiftleri birbirini dengelemelidir? (birden çok)","a":"Dengeli uçuşta itki sürüklemeyi, taşıma ağırlığı dengeler.","o":[["İtki ile sürükleme",true],["Taşıma ile ağırlık",true],["İtki ile taşıma",false],["Sürükleme ile ağırlık",false]]},{"m":"Kanat profilinin üst yüzeyinden geçen havanın hızı ve basıncı alt yüzeye göre nasıldır?","a":"Üstteki düşük basınç, taşıma kuvvetini oluşturur.","o":[["Üst yüzeyde hava daha hızlı akar ve Bernoulli ilkesine göre basınç düşer",true],["Üst yüzeyde hava daha yavaş akar ve basınç artar",false],["Üst ve alt basınçlar her zaman eşittir",false],["Hız arttıkça basınç da artar",false]]},{"m":"Kanat profilinde hücum kenarı ile firar kenarını birleştiren düz çizgiye ne ad verilir?","a":"Akort çizgisi hücum ve firar kenarları arasındaki referans doğrudur.","o":[["Akort çizgisi (chord line)",true],["Kamber çizgisi (camber line)",false],["Hücum açısı",false],["Kalınlık oranı",false]]},{"m":"Kanat profilinin üst ve alt yüzeyleri arasındaki orta noktaları birleştiren eğriye ne denir?","a":"Orta kamber çizgisi profilin eğriliğini tanımlar.","o":[["Orta kamber çizgisi (mean camber line)",true],["Akort çizgisi",false],["Kanat açıklığı vektörü",false],["Hücum kenarı teğeti",false]]},{"m":"Taşıma kuvveti formülünde hangi değişkenler yer alır? (birden çok)","a":"Taşıma = 1/2 x yoğunluk x hız² x alan x taşıma katsayısı.","o":[["Hava yoğunluğu",true],["Uçuş hızı",true],["Kanat alanı",true],["Motor devri (RPM)",false]]},{"m":"Sürükleme formülüne göre hız arttıkça sürükleme kuvveti nasıl değişir?","a":"Sürükleme hızın karesiyle artar.","o":[["Hızın karesiyle orantılı olarak artar",true],["Hız arttıkça sıfırlanır",false],["Hız ile ilişkisi yoktur",false],["Hızın küpüyle ters orantılı azalır",false]]},{"m":"Pervaneli hava araçlarında itki üretiminin temel fiziksel prensibi nedir?","a":"Pervane havayı geriye iter, tepki kuvveti aracı ileri iter.","o":[["Newton'un üçüncü yasası: havanın geriye doğru ivmelendirilmesi",true],["Yalnızca kanat altındaki basınç farkı",false],["Pervanenin ağırlık merkezini değiştirmesi",false],["Manyetik alan indüksiyonu",false]]},{"m":"Pervane itki verimini hangi faktörler etkiler? (birden çok)","a":"İtki performansı hatve, çap, kanat sayısı ve devire bağlıdır.","o":[["Pervane hatvesi (pitch)",true],["Pervane çapı ve kanat sayısı",true],["Motor devri",true],["Gövdenin boya rengi",false]]},{"m":"Sabit kanatlı hava aracında stabilite (kararlılık) nedir?","a":"Stabilite, bozulma sonrası dengeye dönme yeteneğidir.","o":[["Dış etkiyle dengesi bozulduğunda aracın tekrar eski uçuş durumuna dönme eğilimi",true],["Aracın havada hiç yön değiştirmemesi",false],["Motor devrinin sabit tutulması",false],["Kanat alanının gövde alanına eşit olması",false]]},{"m":"Statik stabilite ile dinamik stabilite arasındaki fark nedir?","a":"Dinamik stabilite zaman içindeki sönümlenmeyi kapsar.","o":[["Statik stabilite bozulma sonrası ilk tepki eğilimini, dinamik stabilite salınımların zamanla sönümlenmesini inceler",true],["Statik yerde, dinamik havada geçerlidir",false],["Statik motor gücüne, dinamik yakıt miktarına bağlıdır",false],["Aralarında fark yoktur",false]]},{"m":"İHA'nın taşıma kuvveti formülünde hangi değişkenler yer alır? (birden çok)","a":"Batarya özellikleri taşıma formülünde yer almaz.","o":[["Hava yoğunluğu",true],["Uçuş hızı",true],["Kanat yüzey alanı",true],["Batarya hücre sayısı ve kapasitesi",false]]},{"m":"L/D (taşıma/sürükleme) oranının yüksek olması ne anlama gelir?","a":"Yüksek L/D iyi süzülme ve verimli uçuş demektir.","o":[["Aracın aerodinamik verimliliğinin yüksek olduğunu, az sürüklemeyle çok taşıma ürettiğini",true],["Motorun batarya tüketiminin bittiğini",false],["Ağırlığın sıfıra indiğini",false],["İniş takımlarının açık kilitlendiğini",false]]},{"m":"Hava yoğunluğunun azalması (örneğin yüksek rakımda) İHA performansını nasıl etkiler?","a":"Düşük yoğunluk, taşıma ve itkiyi düşürür.","o":[["Taşıma ve pervane itkisi azalır, kalkış mesafesi uzar",true],["Motor verimi ve taşıma kapasitesi artar",false],["Performansa etkisi yoktur",false],["Hız kendiliğinden iki katına çıkar",false]]}]$json$::jsonb) loop
    if exists (select 1 from public.questions where quiz_id = v_quiz and metin = r->>'m') then continue; end if;
    v_sira := v_sira + 1;
    insert into public.questions (quiz_id, metin, sira, aciklama)
      values (v_quiz, r->>'m', v_sira, r->>'a') returning id into v_q;
    j := 0;
    for o in select * from jsonb_array_elements(r->'o') loop
      j := j + 1;
      insert into public.question_options (question_id, metin, dogru, sira)
        values (v_q, o->>0, (o->>1)::boolean, j);
    end loop;
  end loop;
end $q$;

