-- GCJC4Pwmg7A 38:50: Güvenli İHA operasyonu için meteoroloji raporlarında hangi sınırlamala
do $q$
declare v_quiz uuid; v_q uuid; v_sira int; r jsonb; o jsonb; j int;
begin
  select z.id into v_quiz from public.quizzes z join public.modules m on m.id = z.module_id
   where m.ad = 'Aerodinamik ve Uçuş Mekaniği' and z.zorluk = 'zor' limit 1;
  if v_quiz is null then raise notice 'Quiz yok, atlanıyor: Aerodinamik ve Uçuş Mekaniği zor'; return; end if;
  select coalesce(max(sira), 0) into v_sira from public.questions where quiz_id = v_quiz;
  for r in select * from jsonb_array_elements($json$[{"m":"Sürüklemeyi azaltmak ve yakıt verimliliğini artırmak için uçaklarda kalkıştan hemen sonra hangi uygulama yapılır?","a":"Açık iniş takımları sürüklemeyi artırır, bu yüzden kalkıştan sonra toplanır.","o":[["İniş takımları kapatılır",true],["Kanatlar sökülür",false],["Motor gücü kapatılıp süzülmeye geçilir",false],["Pervaneler ters yöne döndürülür",false]]},{"m":"Uçak tasarımında ağırlığı azaltırken dikkat edilmesi gereken en kritik denge nedir?","a":"Hafiflik, yapısal dayanıklılık pahasına sağlanamaz.","o":[["Hafiflik sağlanırken yapısal dayanıklılıktan ödün verilmemelidir",true],["Rengin aerodinamik sürtünmeyi etkilemeyecek şekilde seçilmesi",false],["Motor sayısının her zaman tek sayıda tutulması",false],["Kanat açıklığının gövde boyundan kısa olması",false]]},{"m":"Simetrik ve kamberli kanat profilleri için hangileri doğrudur? (birden çok)","a":"Simetrik profiller akrobasi dışında kuyruk yüzeylerinde de kullanılır; kamberli profil sıfır açıda taşıma verir.","o":[["Simetrik profilde üst ve alt kavisler aynıdır, sıfır hücum açısında taşıma üretmez",true],["Kamberli profil sıfır hücum açısında bile taşıma üretebilir",true],["Simetrik profiller yalnızca akrobasi uçaklarında kullanılır",false],["Kamberli profillerin hücum kenarı sivri, simetriklerinki künttür",false]]},{"m":"Hücum açısı kritik sınırı aştığında akış ve taşıma nasıl değişir? (birden çok)","a":"Kritik açının ötesinde akım ayrılır ve taşıma kaybolur.","o":[["Kanat üzerindeki akış bozulur (türbülanslı hale gelir)",true],["Taşıma ani düşer (stall)",true],["Taşıma maksimumda sabit kalır",false],["Akış kusursuz laminer akışa dönüşür",false]]},{"m":"Parazit sürükleme (parasite drag) neleri kapsar?","a":"Parazit sürükleme taşıma üretmeyen gövde dirençleridir.","o":[["Yüzey sürtünmesi ve form sürüklemesi gibi gövde dirençlerini",true],["Yalnızca taşıma üretiminden doğan direnci",false],["Motorun iç mekanik sürtünmelerini",false],["Pil sıcaklığından oluşan direnci",false]]},{"m":"İndüklenmiş sürükleme neden kaynaklanır ve hızla nasıl değişir?","a":"İndüklenmiş sürükleme düşük hızda ve yüksek hücum açısında fazladır.","o":[["Taşıma üretirken kanat uçlarındaki girdaplardan kaynaklanır ve hız arttıkça azalır",true],["Egzoz türbülansından kaynaklanır ve hız arttıkça artar",false],["İniş takımlarından kaynaklanır, hızla ilgisi yoktur",false],["Yalnızca yerde (sıfır hızda) geçerlidir",false]]},{"m":"Jet motorları ile pervaneli motorların itki üretimi arasındaki temel fark nedir?","a":"Jet yüksek egzoz hızıyla, pervane geniş hava kütlesini ivmelendirerek itki üretir.","o":[["Jet motorları küçük gaz kütlesini yüksek hızla atar, pervaneler büyük hava kütlesini daha düşük ivmeyle hareket ettirir",true],["Jet motorları yalnızca yerde itki üretir",false],["Pervaneli motorlar itki üretmez, yalnızca taşıma sağlar",false],["Jet motorları yakıt tüketmeden itki sağlar",false]]},{"m":"Statik itki (static thrust) neyi ifade eder?","a":"Statik itki, hızın sıfır olduğu kalkış anındaki itkidir.","o":[["Aracın hareket etmediği (hız sıfır) anda motor-pervanenin ürettiği itkiyi",true],["Maksimum seyir hızında üretilen itkiyi",false],["Motor kapalıyken süzülme direncini",false],["Bataryanın boşaldığı andaki akım değerini",false]]},{"m":"Boyuna stabiliteyi ve pitch hareketini kontrol eden kuyruk yüzeyi hangisidir?","a":"Pitch eksenindeki stabilite ve kontrol yatay kuyrukta sağlanır.","o":[["Yatay stabilizatör ve elevator",true],["Dikey kuyruk (rudder)",false],["Kanat uçlarındaki wingletler",false],["Ana kanat flapları",false]]},{"m":"Yönsel (directional) stabilite ve yaw kontrolü için hangi yüzeyler kullanılır? (birden çok)","a":"Yönsel stabiliteyi dikey kuyruk, yaw kontrolünü rudder sağlar.","o":[["Dikey stabilizatör (fin)",true],["Rudder",true],["Elevator",false],["Ana kanat aileronları",false]]},{"m":"Aşırı stabil (over-stable) bir uçak tasarımının dezavantajı nedir?","a":"Aşırı stabil uçaklar manevra kabiliyetinden kaybeder.","o":[["Manevra yapmakta zorlanır, kumanda komutlarına hantal tepki verir",true],["Sürekli kontrolden çıkıp takla atar",false],["Taşıma kuvveti sıfırlanır",false],["Motorlar aşırı ısınır",false]]},{"m":"Yük taşıma verimliliğini artırmak için kanat tasarımında hangileri optimize edilir? (birden çok)","a":"Yüksek L/D ve uygun aspect ratio verimi artırır.","o":[["Narinlik oranı (aspect ratio) yüksek tutularak indüklenmiş sürükleme azaltılır",true],["Uygun kanat profili seçilerek taşıma/sürükleme (L/D) oranı maksimize edilir",true],["Gövde yüzeyi pürüzlü bırakılarak türbülans artırılır",false],["Kanat alanı olabildiğince küçültülür",false]]},{"m":"Hız arttıkça parazit sürükleme ve indüklenmiş sürükleme nasıl davranır?","a":"Parazit sürükleme hızla artar, indüklenmiş sürükleme düşük hızda fazladır.","o":[["Parazit sürükleme artar, indüklenmiş sürükleme azalır",true],["İkisi de sürekli azalır",false],["Hızın sürükleme türleri üzerinde etkisi yoktur",false],["İndüklenmiş sürükleme artar, parazit sürükleme azalır",false]]},{"m":"Maksimum menzil için hangi aerodinamik koşulda uçulmalıdır?","a":"Maksimum menzil L/D'nin en yüksek olduğu noktada elde edilir.","o":[["Taşıma/sürükleme oranının (L/D) en yüksek olduğu optimum hız ve hücum açısında",true],["Gaz kolu tam açıkken",false],["Hücum açısı sıfıra sabitlenerek",false],["İniş takımları açık tutularak",false]]},{"m":"İHA stall durumuna girdiğinde yapılması gereken ilk doğru hamle nedir?","a":"Stall'dan çıkmak için hücum açısı kritik değerin altına düşürülmelidir.","o":[["Burun aşağı verilerek hücum açısı düşürülür ve hız kazanılır",true],["Gaz kapatılıp elevator çekilmeye devam edilir",false],["Rudder sonuna kadar sağa sabitlenir",false],["Aileronlarla kanatlar dik konuma getirilir",false]]},{"m":"Sıcak yaz günü ile soğuk gün arasındaki uçuş farkı için hangileri doğrudur? (birden çok)","a":"Sıcaklık arttıkça yoğunluk düşer.","o":[["Sıcak havada yoğunluk düştüğü için aynı taşımayı üretmek daha yüksek hız gerektirir",true],["Soğuk havada yoğunluk fazla olduğu için İHA daha iyi performans verir",true],["Sıcaklığın taşıma kuvvetine etkisi yoktur",false],["Sıcak havada motorlar daha az akım çekerek batarya ömrünü iki katına çıkarır",false]]},{"m":"Bağıl nemin artması motor ve pervane performansını dolaylı olarak nasıl etkiler?","a":"Nemli hava kuru havadan daha az yoğundur.","o":[["Su buharı kuru havadan hafif olduğu için yoğunluğu bir miktar düşürür ve verimi azaltır",true],["Nem arttıkça motor gücü ve itki çok artar",false],["Nem yalnızca GPS uydu sayısını etkiler",false],["Nem motor soğumasını durdurarak yanmasına yol açar",false]]},{"m":"Güvenli İHA operasyonu için meteoroloji raporlarında hangi sınırlamalara dikkat edilir? (birden çok)","a":"Rüzgar, hamle, görüş ve bulut tabanı uçuş emniyetini belirler.","o":[["Maksimum rüzgar hızı ve ani hamle (gust) limitleri",true],["Görüş mesafesi ve bulut tabanı yüksekliği",true],["Zemindeki toprak rengi",false],["Bulutların estetik görünümü",false]]}]$json$::jsonb) loop
    if exists (select 1 from public.questions where quiz_id = v_quiz and metin = r->>'m') then continue; end if;
    v_sira := v_sira + 1;
    insert into public.questions (quiz_id, metin, sira, aciklama)
      values (v_quiz, r->>'m', v_sira, r->>'a') returning id into v_q;
    j := 0;
    for o in select * from jsonb_array_elements(r->'o') loop
      j := j + 1;
      insert into public.question_options (question_id, metin, dogru, sira)
        values (v_q, o->>0, (o->>1)::boolean, j);
    end loop;
  end loop;
end $q$;

